window.products.push({"id":1034698,"name":"(D) Laguiole French Hand Made Pradel 1920 Steak cutlery 8 Inch, Vintage","category":"homeandappliances","retail price":24.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/31-W2OGJwOL._AC_.jpg","description":"The Laguiole cutlery has been used in the south of France for over 200 years. The blade, made of high-grade stainless steel, is stamped, then ground and then polished in over 25 different manual production stages. Soft and subtle to the touch, a Laguiole cutlery will stay sharp and will never rust.","images":["https://m.media-amazon.com/images/I/31-W2OGJwOL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"GIFTS PLAZA","source_asin":"B07VCKNFK7","category_path":"Home & Kitchen"},"sku":"BM-1034698","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07VCKNFK7","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07VCKNFK7","price_pending":true,"merchant_ready":false});
